    level: "N4",
    surface: "利用",
    reading: "りよう",
    meaningZh: "利用、使用",
    meaningI18n: { "en": "use" },
    promptLabel: "漢字読み",
    instructionZh: "選出底線詞語的正確讀音。",
    instructionI18n: { "en": "Choose the correct reading of the underlined word." },
    promptText: "図書館は だれでも 無料で「利用」できます。",
