    explanationI18n: { "en": "「政」takes the long vowel「せい」and「治」is voiced here to「じ」, so「政治」＝せいじ. In「せいち」the「治」stays unvoiced (「ち」instead of「じ」);「せえじ」spells the long vowel「せい」wrongly as「せえ」;「しょうじ」misreads「政（せい）」as「しょう」. Only「せいじ」is correct." },
