    explanationI18n: { "en": "「予」is the short「よ」and「定」is the long「てい」, so「予定」＝よてい.「ようてい」misreads「予（よ）」as the long「よう」;「よてえ」spells the long vowel「てい」wrongly as「てえ」;「よでい」wrongly voices「定（てい）」to「でい」. Only「よてい」is correct." },
    exampleJapanese: "来月の旅行の予定はもう決まりました。",
