    surface: "〜なくてもいい",
    reading: "なくてもいい",
    meaningZh: "不必…、不…也可以",
    meaningI18n: { "en": "there's no need to ...; it's fine not to ..." },
    promptLabel: "文法形式選擇",
    instructionZh: "句中填空：依文脈選最自然的文法。",
    instructionI18n: { "en": "Fill in the blank: choose the grammar that fits the context most naturally." },
    promptText: "まだ 時間が ある から、そんなに 急が ___ よ。",
