    explanation: "「家」讀「か」、「族」濁化讀「ぞく」，故「家族」＝かぞく。「かそく」沒把「族」讀濁音（清音「そく」，近「加速」）；「けぞく」把「家（か）」誤讀成「け」；「かずく」把「ぞ」誤讀成「ず」。唯「かぞく」正確。",
    explanationI18n: { "en": "「家」is「か」and「族」is voiced to「ぞく」, so「家族」＝かぞく.「かそく」leaves「族」unvoiced (「そく」, close to「加速」);「けぞく」misreads「家（か）」as「け」;「かずく」misreads「ぞ」as「ず」. Only「かぞく」is correct." },
    exampleJapanese: "日曜日は家族といっしょに公園でお弁当を食べました。",
