    meaningI18n: { "en": "finally; at last (after difficulty)" },
    promptLabel: "類義替換",
    instructionZh: "選與「」中詞語意思最接近的選項。",
    instructionI18n: { "en": "Choose the option closest in meaning to the word in 「」." },
    promptText: "三十分も歩いて、「やっと」駅に着いた。",
