    explanation: "「有名」表示廣為人知，≒「よく知られている」。「新しくできた」是「新建成的」（描述新舊）；「とても静かな」是「很安靜的」（描述氛圍）；「少し珍しい」是「有點稀奇的」（描述稀有度）。三者都不等於「為人所知」，唯「よく知られている」與「有名」同義。",
    explanationI18n: { "en": "「有名」means widely known, ≒「よく知られている」. 「新しくできた」means \"newly built\" (describing age); 「とても静かな」means \"very quiet\" (describing atmosphere); 「少し珍しい」means \"a bit unusual\" (describing rarity). None of these mean \"known by many people\"; only 「よく知られている」is synonymous with 「有名」." },
