    meaningZh: "決定、定下",
    meaningI18n: { "en": "to decide; to settle on" },
    promptLabel: "詞彙用法",
    instructionZh: "選出該詞語使用最自然的句子。",
    instructionI18n: { "en": "Choose the sentence in which the word is used most naturally." },
    promptText: "次の文のうち、「決める」の使い方が最も適切なものはどれか。",
    promptContextZh: "大家商量之後，定下了去旅行的日子。",
    promptContextI18n: { "en": "After talking it over together, we settled on the day for the trip." },
