    explanation: "「決める」＝做出選擇、把事情定下來，本句「大家商量後決定旅行的日子」最自然。開電燈用「つける」；和朋友碰面用「会う」；把行李搬上樓用「運ぶ」。三句搭配皆不通，唯第一句成立。",
    explanationI18n: { "en": "「決める」means to make a choice and finalize something, so \"after discussing it, we decided on the trip date\" is the most natural. To turn on a light you use 「つける」; to meet a friend you use 「会う」; to carry luggage upstairs you use 「運ぶ」. The other three combinations don't work; only the first sentence is valid." },
    exampleJapanese: "みんなで相談して、旅行に行く日を決めた。",
    exampleMeaningZh: "大家商量後，決定了去旅行的日子。"
