    meaningZh: "打擾、妨礙",
    meaningI18n: { "en": "to disturb, to get in the way" },
    promptLabel: "詞彙填空",
    instructionZh: "句中填空：選最自然的詞語。",
    instructionI18n: { "en": "Fill in the blank: choose the most natural word." },
    promptText: "弟は私が勉強しているとき、いつも話しかけてきて、本当に ___ だ。",
