    explanation: "正解「うんてん」：運=うん、転=てん，無濁音、無促音。干擾「うんでん」把第二字濁化成「でん」（清濁陷阱），不存在此讀法。「うってん」多插促音「っ」（促音陷阱），讀法不成立。「うんてい」把「てん」誤聽成「てい」（近形/撥音與長音混淆），不是此詞讀音。四選只有一個成立。",
    explanationI18n: { "en": "The answer 「うんてん」: 運=うん, 転=てん, with no voiced sound and no double consonant. The distractor 「うんでん」 voices the second character into 「でん」 (voiced/unvoiced trap); this reading doesn't exist. 「うってん」 inserts an extra double consonant 「っ」 (sokuon trap), which is not a valid reading. 「うんてい」 mishears 「てん」 as 「てい」 (confusion between the moraic nasal and a long vowel), which is not this word's reading. Only one of the four works." },
    exampleJapanese: "兄は毎朝、車を運転して会社へ行きます。",
    exampleMeaningZh: "哥哥每天早上開車去公司。"
