    explanation: "正解「ぶんか」：文=ぶん、化=か。干擾「ぶんが」把「か」濁化成「が」（清濁陷阱），無此讀法。「ぷんか」把首音「ぶ」誤作半濁「ぷ」（近形假名陷阱），不成立。「ぼんか」把「ぶん」誤作「ぼん」（母音混淆），不是此詞讀音。只有一個成立。",
    explanationI18n: { "en": "The answer 「ぶんか」: 文=ぶん, 化=か. The distractor 「ぶんが」 voices 「か」 into 「が」 (voiced/unvoiced trap); no such reading exists. 「ぷんか」 misreads the first sound 「ぶ」 as the semi-voiced 「ぷ」 (similar-kana trap) and doesn't work. 「ぼんか」 misreads 「ぶん」 as 「ぼん」 (vowel confusion) and is not this word's reading. Only one works." },
    exampleJapanese: "日本の文化について、もっと勉強したいです。",
