    expectedAnswer: "りょうり",
    options: ["りょうり", "りょり", "りゅうり", "りょうりょ"],
    explanation: "正解「りょうり」：料=りょう（含長音）、理=り。干擾「りょり」漏掉長音「う」（長音脫落陷阱），讀法不成立。「りゅうり」把拗音「りょ」誤作「りゅう」（近形拗音陷阱），不是此詞讀音。「りょうりょ」把第二字「り」誤作拗音「りょ」（多餘拗音），不成立。只有一個成立。",
    explanationI18n: { "en": "The answer 「りょうり」: 料=りょう (with a long vowel), 理=り. The distractor 「りょり」 drops the long vowel 「う」 (dropped-long-vowel trap), so the reading fails. 「りゅうり」 misreads the contracted sound 「りょ」 as 「りゅう」 (similar contracted-sound trap) and is not this word's reading. 「りょうりょ」 misreads the second character 「り」 as the contracted sound 「りょ」 (an extra contracted sound) and doesn't work. Only one works." },
