    explanation: "正解「せわ」：世=せ、話=わ（世＝せ、話＝わ，皆為音讀）。干擾「せいわ」多加長音「い」（長音陷阱），讀法不成立。「ぜわ」把首音「せ」濁化（清濁陷阱），無此讀法。「せば」把「わ」誤作「ば」（近形假名わ／ば混淆），不是此詞讀音。只有一個成立。",
    explanationI18n: { "en": "The answer 「せわ」: 世=せ, 話=わ (世=せ, 話=わ, both on'yomi). The distractor 「せいわ」 adds an extra long vowel 「い」 (long-vowel trap), so the reading fails. 「ぜわ」 voices the first sound 「せ」 (voiced/unvoiced trap); no such reading exists. 「せば」 misreads 「わ」 as 「ば」 (similar-kana わ/ば confusion) and is not this word's reading. Only one works." },
