    explanationI18n: { "en": "The answer 「ちず」: 地=ち, 図=ず. The distractor 「ちす」 unvoices 「ず」 into 「す」 (voiced/unvoiced trap), so the reading fails. 「じず」 voices the first sound 「ち」 into 「じ」 (voiced/unvoiced trap); no such reading exists. 「ちづ」 replaces 「ず」 with the similar kana 「づ」 (a homophone similar-kana trap; the standard spelling is ず) and is not this word's correct kana. Only one works." },
    exampleJapanese: "知らない町では、地図を見ながら歩きます。",
