    explanationI18n: { "en": "The answer 「くうこう」: 空=くう (long vowel), 港=こう (long vowel). The distractor 「くこう」 drops the first long vowel 「う」 (dropped-long-vowel trap), so the reading fails. 「くうごう」 voices 「こう」 into 「ごう」 (voiced/unvoiced trap); no such reading exists. 「くうこ」 drops the second long vowel (dropped long vowel) and is not this word's reading. Only one works." },
