    explanationI18n: { "en": "The answer 「こうじょう」: 工=こう (long vowel), 場=じょう (contracted sound plus long vowel). The distractor 「こうじょ」 drops the long vowel 「う」 of the second character (dropped-long-vowel trap), so the reading fails. 「こじょう」 drops the first long vowel (dropped long vowel) and doesn't work. 「こうしょう」 unvoices 「じょう」 into 「しょう」 (voiced/unvoiced trap) and is not this word's reading. Only one works." },
