    explanation: "「似る」是『相像』。正解『顔がお母さんに似ている』表示長得像媽媽。其餘誤用：『駅で友だちに似ている』應用『会う（遇見）』；『窓の外を似てください』應用『見て（看）』；『壁の色を白に似た』應用『した／塗った（漆成）』。",
    explanationI18n: { "en": "似る means \"to resemble.\" The answer 顔がお母さんに似ている means he looks like his mother. The others are misuses: 「駅で友だちに似ている」 should use 会う (\"meet\"); 「窓の外を似てください」 should use 見て (\"look\"); 「壁の色を白に似た」 should use した／塗った (\"painted\")." },
