    explanation: "「間に合う」是『趕得上』。正解表示趕上了九點的電車。其餘誤用：『九時の電車を間に合った』應用『に乗った（搭上）』；『駅で友だちと間に合った』應用『会った（碰面）』；『宿題を明日までに間に合った』應用『終わらせた／出した（完成／交出）』。",
    explanationI18n: { "en": "間に合う means \"to make it in time.\" The answer means catching the nine o'clock train. The others are misuses: 「九時の電車を間に合った」 should use に乗った (\"boarded\"); 「駅で友だちと間に合った」 should use 会った (\"met\"); 「宿題を明日までに間に合った」 should use 終わらせた／出した (\"finished / handed in\")." },
