    promptLabel: "類義替換",
    instructionZh: "選與「」中詞語意思最接近的選項。",
    instructionI18n: { "en": "Choose the option closest in meaning to the word in quotes." },
    promptText: "この本は「だいたい」読みました。",
    promptContextZh: "這本書我差不多讀完了。",
