    explanationI18n: { "en": "The correct answer 「おや」is the kun'yomi of 「親」(parents) used as a noun. The distractor 「あや」is a similar-looking kana substitution, not a reading of 「親」; 「おお」and 「おか」are both just visually similar kana strings and are not valid readings of 「親」." },
