    explanation: "正解「きゅうこう」是「急行（快車）」的標準音讀。干擾「きゅこう」少了「きゅう」的長音；「きゅうごう」把「こう」錯讀成濁音「ごう」；「ぎゅうこう」把「きゅう」錯讀成「ぎゅう」。三者都不是「急行」的合法讀音。",
    explanationI18n: { "en": "The correct answer 「きゅうこう」is the standard on'yomi of 「急行」(express train). The distractor 「きゅこう」is missing the long vowel in 「きゅう」; 「きゅうごう」wrongly voices 「こう」into 「ごう」; 「ぎゅうこう」wrongly reads 「きゅう」as 「ぎゅう」. None of the three is a valid reading of 「急行」." },
