    promptContextZh: "形容一位學生個性的情境。",
    promptContextI18n: { "en": "A scene describing a student's personality." },
    expectedAnswer: "まじめ",
    options: ["まじめ", "まじめい", "まめじ", "ましめ"],
    explanation: "正解「まじめ」是「真面目」的固定讀音（熟字訓）。干擾「まじめい」多加了「い」的長音；「まめじ」把「じ」「め」順序顛倒；「ましめ」把濁音「じ」錯讀成清音「し」。三者皆非「真面目」的讀法。",
    explanationI18n: { "en": "The correct answer 「まじめ」 is the fixed reading of 「真面目」 (a special kanji reading, jukujikun). The distractor 「まじめい」 adds an extra long vowel 「い」; 「まめじ」 swaps the order of 「じ」 and 「め」; and 「ましめ」 misreads the voiced 「じ」 as the unvoiced 「し」. None of the three are valid readings of 「真面目」." },
    exampleJapanese: "彼はとても真面目な学生です。",
