    explanationI18n: { "en": "The correct answer 「とし」 is the on'yomi of 「都市」. The distractor 「とうし」 adds a long vowel after 「と」; 「とじ」 misreads 「し」 as the voiced 「じ」; and 「どし」 misreads 「と」 as the voiced 「ど」. None of the three are legitimate readings of 「都市」." },
