    level: "N4",
    surface: "計画",
    reading: "けいかく",
    meaningZh: "計畫、規劃",
    meaningI18n: { "en": "plan, planning" },
    promptLabel: "漢字読み",
    instructionZh: "選出底線詞語的正確讀音。",
    instructionI18n: { "en": "Choose the correct reading of the underlined word." },
    promptText: "夏休みの「計画」をみんなで考えました。",
