    expectedAnswer: "つつんで",
    options: ["つつんで", "ならべて", "あつめて", "ひろって"],
    explanation: "正解「つつんで」＝用紙把禮物包起來，與「かみで・プレゼント」吻合。「ならべて」＝排列，用紙把禮物排列不合語意。「あつめて」＝收集，「かみで あつめる」搭配不成立。「ひろって」＝撿拾，禮物不是掉在地上的東西，語意不合。只有「つつんで」成立。",
    explanationI18n: { "en": "The correct answer 「つつんで」 means \"wrapped the gift in paper,\" matching 「かみで・プレゼント」. 「ならべて」 means \"to arrange/line up\"; arranging a gift with paper doesn't fit. 「あつめて」 means \"to gather/collect\"; 「かみで あつめる」 doesn't form a valid combination. 「ひろって」 means \"to pick up\"; a gift isn't something dropped on the ground, so the meaning doesn't fit. Only 「つつんで」 is valid." },
