    promptLabel: "詞彙填空",
    instructionZh: "句中填空：選最自然的詞語。",
    instructionI18n: { "en": "Fill in the blank with the most natural word." },
    promptText: "あした くうこうへ 父を ___ に 行く つもりです。",
