    expectedAnswer: "なくした",
    options: ["なくした", "もらった", "かりた", "あらった"],
    explanation: "正解「なくした」＝弄丟，與「家に 入れなくて こまった（進不了家很困擾）」因果一致。「もらった」＝得到，拿到鑰匙反而能進門，語意相反。「かりた」＝借來，借到鑰匙也能開門，無法解釋進不去。「あらった」＝洗，洗鑰匙不會導致進不了家，搭配不合。只有「なくした」成立。",
    explanationI18n: { "en": "The correct answer 「なくした」 means \"lost,\" which is causally consistent with 「家に 入れなくて こまった（couldn't get into the house, which was a problem）」. 「もらった」 means \"received\"; getting a key would actually let you in, so the meaning is reversed. 「かりた」 means \"borrowed\"; borrowing a key would also let you open the door, so it can't explain being unable to get in. 「あらった」 means \"washed\"; washing a key wouldn't keep you out of the house, so it doesn't fit. Only 「なくした」 is valid." },
