    explanationI18n: { "en": "「牛」 reads as 「ぎゅう」 (voiced, with a contracted long vowel) and 「乳」 reads as 「にゅう」, so 「牛乳」＝ぎゅうにゅう. 「きゅうにゅう」 misreads 「牛」 as the unvoiced 「きゅう」; 「ぎゅうにゅ」 drops the long vowel of 「乳」; and 「ぎゅにゅう」 drops the long vowel of 「牛」. None of these three readings would be accepted by native speakers—only 「ぎゅうにゅう」 is valid." },
