    explanation: "「台所」是慣用讀法＝だいどころ（「台」だい、「所」連濁讀「どころ」）。「たいどころ」把「台」誤讀成清音「たい」；「だいところ」漏掉「所」的連濁；「だいどごろ」把濁音放錯位置。三者都不成立，唯「だいどころ」正確。",
    explanationI18n: { "en": "「台所」 has the customary reading だいどころ (「台」 as だい, 「所」 with sequential voicing read as 「どころ」). 「たいどころ」 misreads 「台」 as the unvoiced 「たい」; 「だいところ」 omits the sequential voicing of 「所」; and 「だいどごろ」 puts the voicing in the wrong place. None of these three are valid—only 「だいどころ」 is correct." },
