    meaningI18n: { "en": "sad / sorrowful" },
    promptLabel: "類義替換",
    instructionZh: "選與「」中詞語意思最接近的選項。",
    instructionI18n: { "en": "Choose the option closest in meaning to the word in quotation marks." },
    promptText: "犬が 死んで、わたしは とても 「悲しい」 気もちです。",
    promptContextZh: "狗死了，我的心情非常悲傷。",
