    level: "N4",
    surface: "研究",
    reading: "けんきゅう",
    meaningZh: "研究",
    meaningI18n: { "en": "research" },
    promptLabel: "漢字読み",
    instructionZh: "選出底線詞語的正確讀音。",
    instructionI18n: { "en": "Choose the correct reading of the underlined word." },
    promptText: "兄は大学で日本語の「研究」をしています。",
